<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { apiClient } from '@/services/api'; import type { AttendanceRecord, Employee } from '@/types'
const rows=ref<AttendanceRecord[]>([]); const employees=ref<Employee[]>([]); const employeeId=ref(''); const startDate=ref(''); const endDate=ref(''); const loading=ref(false); const error=ref(''); const page=ref(1); const total=ref(0); const limit=20
async function load(){loading.value=true;error.value='';try{const r=await apiClient.listAttendance(employeeId.value||undefined,startDate.value||undefined,endDate.value||undefined,(page.value-1)*limit,limit);rows.value=r.items;total.value=r.total}catch(e){error.value=apiClient.getErrorMessage(e)}finally{loading.value=false}}
async function init(){try{employees.value=(await apiClient.listEmployees(0,200)).items}catch(e){error.value=apiClient.getErrorMessage(e)};await load()};onMounted(init)
</script>
<template><main class="space-y-6"><h1 class="text-2xl font-bold">Attendance</h1><div v-if="error" class="rounded bg-red-50 p-3 text-red-700">{{ error }}</div><form class="flex flex-wrap gap-3 rounded-lg bg-white p-4 shadow" @submit.prevent="page=1;load()"><select v-model="employeeId" class="rounded border p-2"><option value="">All employees</option><option v-for="e in employees" :key="e.id" :value="e.id">{{ e.full_name }}</option></select><input v-model="startDate" type="date" class="rounded border p-2" /><input v-model="endDate" type="date" class="rounded border p-2" /><button class="rounded bg-indigo-600 px-4 py-2 text-white">Filter</button></form><div class="overflow-x-auto rounded-lg bg-white shadow"><table class="min-w-full text-left text-sm"><thead><tr class="border-b bg-slate-50"><th class="p-3">Employee ID</th><th class="p-3">Date</th><th class="p-3">Check in</th><th class="p-3">Check out</th><th class="p-3">Status</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id" class="border-b"><td class="p-3">{{ r.employee_id }}</td><td class="p-3">{{ r.work_date }}</td><td class="p-3">{{ new Date(r.check_in_at).toLocaleString() }}</td><td class="p-3">{{ r.check_out_at ? new Date(r.check_out_at).toLocaleString() : '—' }}</td><td class="p-3">{{ r.status }}</td></tr></tbody></table></div><div class="flex justify-between"><span>{{ total }} records</span><div class="flex gap-2"><button class="rounded border px-3 py-1" :disabled="page===1" @click="page--;load()">Previous</button><button class="rounded border px-3 py-1" :disabled="page*limit>=total" @click="page++;load()">Next</button></div></div></main></template>
